mkdir -p /tmp/inspect && cat > /tmp/inspect/dump.py <<'EOF'
import sys, os, io, zipfile, tarfile, gzip, bz2, lzma, pickletools, json

def dis(data, label):
    print(f"--- pickle dis [{label}] ({len(data)} bytes) ---")
    pos = 0
    stream = 0
    while pos < len(data):
        out = io.StringIO()
        try:
            f = io.BytesIO(data[pos:])
            pickletools.dis(f, out=out)
            consumed = f.tell()
        except Exception as e:
            print(out.getvalue()[:3000])
            print(f"!! dis error at stream {stream} pos {pos}: {e}")
            print("remaining bytes:", data[pos:pos+200])
            break
        print(f"[stream {stream} @ {pos}]")
        print(out.getvalue())
        pos += consumed
        stream += 1
        if stream > 10:
            print("... more streams")
            break

def sniff(data):
    if data[:2] == b"\x1f\x8b": return "gzip"
    if data[:3] == b"BZh": return "bz2"
    if data[:6] == b"\xfd7zXZ\x00": return "xz"
    if data[:4] == b"PK\x03\x04" or zipfile.is_zipfile(io.BytesIO(data)): return "zip"
    if data[:6] == b"\x93NUMPY": return "npy"
    if data[:8] == b"\x89HDF\r\n\x1a\n": return "hdf5"
    try:
        tarfile.open(fileobj=io.BytesIO(data))
        if len(data) >= 512 and data[257:262] == b"ustar": return "tar"
    except Exception:
        pass
    if data[:1] in b"\x80(cI]}" or data[:1] == b"\x80": return "pickle?"
    return "unknown"

def inspect_bytes(data, label, depth=0):
    kind = sniff(data)
    print(f"{'  '*depth}## {label}: sniff={kind} size={len(data)} head={data[:32]!r}")
    if kind == "gzip":
        # possibly multiple members
        print(f"{'  '*depth}gzip; decompressing all members")
        inner = gzip.decompress(data)
        inspect_bytes(inner, label + "|gunzip", depth+1)
    elif kind == "bz2":
        inspect_bytes(bz2.decompress(data), label + "|bunzip2", depth+1)
    elif kind == "xz":
        inspect_bytes(lzma.decompress(data), label + "|unxz", depth+1)
    elif kind == "zip":
        zf = zipfile.ZipFile(io.BytesIO(data))
        for zi in zf.infolist():
            print(f"{'  '*depth} zip member {zi.filename!r} size={zi.file_size} comp={zi.compress_type} hdr_off={zi.header_offset}")
        for zi in zf.infolist():
            if zi.filename.endswith("/"): continue
            member = zf.read(zi)
            inspect_bytes(member, label + "!" + zi.filename, depth+1)
    elif kind == "tar":
        tf = tarfile.open(fileobj=io.BytesIO(data))
        for m in tf.getmembers():
            print(f"{'  '*depth} tar member {m.name!r} type={m.type} size={m.size}")
        for m in tf.getmembers():
            if m.isfile():
                inspect_bytes(tf.extractfile(m).read(), label + "!" + m.name, depth+1)
    elif kind == "npy":
        # parse header
        major = data[6]; minor = data[7]
        if major == 1:
            hlen = int.from_bytes(data[8:10], "little"); hstart = 10
        else:
            hlen = int.from_bytes(data[8:12], "little"); hstart = 12
        header = data[hstart:hstart+hlen]
        print(f"{'  '*depth} npy header: {header!r}")
        body = data[hstart+hlen:]
        if b"'O'" in header or b"object" in header or b'"O"' in header:
            dis(body, label + "|npy-body")
        else:
            print(f"{'  '*depth} npy numeric body {len(body)} bytes")
    elif kind == "hdf5":
        import h5py
        with h5py.File(io.BytesIO(data), "r") as fh:
            for k, v in fh.attrs.items():
                vv = v.decode() if isinstance(v, bytes) else v
                print(f"{'  '*depth} h5 attr {k!r}: {str(vv)[:4000]}")
            def visit(name, obj):
                print(f"{'  '*depth}  h5 obj {name} {type(obj).__name__} attrs={list(obj.attrs.keys())}")
            fh.visititems(visit)
    elif kind == "pickle?":
        dis(data, label)
    else:
        try:
            txt = data.decode("utf-8")
            print(f"{'  '*depth} text: {txt[:3000]}")
        except Exception:
            print(f"{'  '*depth} binary unknown: {data[:200]!r}")
            dis(data, label)

def inspect_path(path):
    print(f"\n\n######## {path} ########")
    if os.path.isdir(path):
        for root, dirs, files in os.walk(path):
            for fn in files:
                p = os.path.join(root, fn)
                print(f"  dir file {p} size={os.path.getsize(p)}")
        return
    with open(path, "rb") as fh:
        data = fh.read()
    inspect_bytes(data, os.path.basename(path))

for p in sys.argv[1:]:
    try:
        inspect_path(p)
    except Exception as e:
        import traceback; traceback.print_exc()
